   import { ApiClient } from './api-client.js';

   interface AuthTokenResponse {
     access_token: string;
     token_type: string;
     expires_in: number;
     created_at: number;
   }

   export class AuthManager {
     private apiClient: ApiClient;
     private clientId: string;
     private clientSecret: string;
     private currentToken: string | null = null;

     constructor(apiClient: ApiClient, clientId: string, clientSecret: string) {
       this.apiClient = apiClient;
       this.clientId = clientId;
       this.clientSecret = clientSecret;
     }

     async authenticate(email: string, password: string): Promise<string> {
       const response = await this.apiClient.post<AuthTokenResponse>('/oauth/token', {
         grant_type: 'password',
         email,
         password,
         client_id: this.clientId,
         client_secret: this.clientSecret,
       });
       this.currentToken = response.access_token;
       this.apiClient.setToken(this.currentToken);
       return this.currentToken;
     }

     async validateToken(): Promise<boolean> {
       if (!this.currentToken) return false;
       try {
         await this.apiClient.get('/oauth/token/info');
         return true;
       } catch {
         return false;
       }
     }

     async revokeToken(): Promise<void> {
       if (this.currentToken) {
         await this.apiClient.post('/oauth/revoke', { token: this.currentToken });
         this.currentToken = null;
         this.apiClient.setToken('');
       }
     }

     getToken(): string | null {
       return this.currentToken;
     }
   }
   ```

