   import { z } from 'zod';
   import { AuthManager } from '../auth.js';
   import { ApiClient } from '../api-client.js';

   // Input schemas
   export const authenticateSchema = z.object({
     email: z.string().email('Valid email required'),
     password: z.string().min(1, 'Password required'),
     company_id: z.string().optional(),
   });

   export const validateTokenSchema = z.object({});
   export const revokeTokenSchema = z.object({});

   // Tool definitions
   export const authToolDefinitions = [
     {
       name: 'authenticate',
       description: 'Sign in via OAuth2 to get a bearer token. Required before using other tools.',
       inputSchema: {
         type: 'object',
         properties: {
           email: { type: 'string', description: 'User email address' },
           password: { type: 'string', description: 'User password' },
           company_id: { type: 'string', description: 'Optional company ID to set as default' },
         },
         required: ['email', 'password'],
       },
     },
     {
       name: 'validate_token',
       description: 'Check if the current authentication token is valid.',
       inputSchema: { type: 'object', properties: {} },
     },
     {
       name: 'revoke_token',
       description: 'Sign out and revoke the current bearer token.',
       inputSchema: { type: 'object', properties: {} },
     },
   ];

   // Tool handlers
   export function createAuthToolHandlers(authManager: AuthManager, apiClient: ApiClient) {
     return {
       authenticate: async (args: unknown) => {
         const parsed = authenticateSchema.parse(args);
         const token = await authManager.authenticate(parsed.email, parsed.password);
         if (parsed.company_id) {
           apiClient.setCompanyId(parsed.company_id);
         }
         return { success: true, message: 'Authentication successful' };
       },
       validate_token: async () => {
         const isValid = await authManager.validateToken();
         return { valid: isValid };
       },
       revoke_token: async () => {
         await authManager.revokeToken();
         return { success: true, message: 'Token revoked' };
       },
     };
   }
   ```

