   ```typescript
   import { authToolDefinitions, createAuthToolHandlers } from './tools/auth.js';

   const authHandlers = createAuthToolHandlers(authManager, apiClient);

   server.setRequestHandler(ListToolsRequestSchema, async () => ({
     tools: [...authToolDefinitions],
   }));

   server.setRequestHandler(CallToolRequestSchema, async (request) => {
     const { name, arguments: args } = request.params;
     try {
       switch (name) {
         case 'authenticate':
           return { content: [{ type: 'text', text: JSON.stringify(await authHandlers.authenticate(args)) }] };
         case 'validate_token':
           return { content: [{ type: 'text', text: JSON.stringify(await authHandlers.validate_token()) }] };
         case 'revoke_token':
           return { content: [{ type: 'text', text: JSON.stringify(await authHandlers.revoke_token()) }] };
         default:
           throw new Error(`Unknown tool: ${name}`);
       }
     } catch (error) {
       return { content: [{ type: 'text', text: JSON.stringify({ error: error.message }) }], isError: true };
     }
   });
   ```

